class Solution:
    def reverse(self, x: int) -> int:
        result = int(str(abs(x))[::-1])
        if result < -(2 ** 31) or result > 2 ** 31 - 1:
            return 0
        return result

class Solution:
    def reverse(self, x: int) -> int:
        sign = -1 if x < 0 else 1
        return sign * int(str(abs(x))[::-1])

class Solution:
    def reverse(self, x: int) -> int:
        sign = -1 if x < 0 else 1
        result = sign * int(str(abs(x))[::-1])
        if result > 2 ** 31 - 1:
            return 2 ** 31 - 1
        if result < -(2 ** 31):
            return -(2 ** 31)
        return result

class Solution:
    def reverse(self, x: int) -> int:
        if x < -(2 ** 31) or x > 2 ** 31 - 1:
            return 0
        sign = -1 if x < 0 else 1
        return sign * int(str(abs(x))[::-1])

class Solution:
    def reverse(self, x: int) -> int:
        result = 0
        n = x
        while n > 0:
            result = result * 10 + n % 10
            n = n // 10
        if result < -(2 ** 31) or result > 2 ** 31 - 1:
            return 0
        return result

class Solution:
    def reverse(self, x: int) -> int:
        sign = -1 if x < 0 else 1
        result = sign * int(str(abs(x))[::-1])
        if result < -(2 ** 31) or result > 2 ** 31 - 1:
            return None
        return result

class Solution:
    def reverse(self, x: int) -> int:
        sign = 1 if x < 0 else -1
        result = sign * int(str(abs(x))[::-1])
        if result < -(2 ** 31) or result > 2 ** 31 - 1:
            return 0
        return result

class Solution:
    def reverse(self, x: int) -> int:
        sign = "-" if x < 0 else ""
        result = sign + str(abs(x))[::-1]
        if int(result) < -(2 ** 31) or int(result) > 2 ** 31 - 1:
            return 0
        return result
